// For locales without full subject prose yet, use localized names plus concise, localized structural copy from the UI and English scientific content only as a last-resort safety fallback.
for (const locale of ["es","fr","de","pt","ru","ja","zh","ar"] as Locale[]) {
  for (const slug of Object.keys(subjectsCatalog) as SubjectSlug[]) {
    const base=subjectsCatalog[slug];
    if (!(subjectTranslations[locale] as any)[slug]) {
      (subjectTranslations[locale] as any)[slug]={...base,eyebrow:subjectFallbackNames[locale][slug]};
    }
  }
}

export function getEducationCopy(locale: Locale): EducationCopy {
  const copy = copies[locale] ?? en;
  const visibleLabCount = visibleSubjectSlugs.reduce((count, slug) => count + subjectsCatalog[slug].simulations.length, 0);
  const updateLabCount = (value: string) => value.replace(/\b70\b/g, String(visibleLabCount));
  return {
    ...copy,
    home: { ...copy.home, labCount: updateLabCount(copy.home.labCount) },
    seo: {
      ...copy.seo,
      homeDescription: updateLabCount(copy.seo.homeDescription),
      libraryDescription: updateLabCount(copy.seo.libraryDescription),
    },
    donate: {
      ...copy.donate,
      seoTitle: copy.donate.seoTitle.replace(/Science Universe/g, siteName),
      seoDescription: copy.donate.seoDescription.replace(/Science Universe/g, siteName),
    },
  };
}

export function getLocalizedSimulation(locale: Locale, simulation: SimulationCard): SimulationCard {
  const translated = simulationTranslations[locale]?.[simulation.slug];
  return {
    ...simulation,
    title: translated?.title ?? simulation.title,
    outcome: translated?.outcome ?? simulation.outcome,
    concepts: translated?.concepts ?? (locale === "en" ? simulation.concepts : ""),
    kind: translated?.kind ?? (locale === "en" ? simulation.kind : ""),
    difficulty: simulation.difficulty,
  };
}

export function getLocalizedSubject(locale: Locale, slug: SubjectSlug): SubjectDefinition {
  const base=subjectsCatalog[slug]; const t=subjectTranslations[locale][slug];
  const copy=getEducationCopy(locale);
  const simulations=base.simulations.map((sim)=>{
    const localized=getLocalizedSimulation(locale,sim);
    const localizedKind = localized.kind || (sim.visualMode === "3d" ? copy.lab.interactive3d : sim.visualMode === "game" ? copy.lab.challenge : copy.lab.interactiveModel);
    const localizedConcepts = localized.concepts || t.concepts.join(" · ");
    return {...localized,kind:localizedKind,concepts:localizedConcepts};
  });
  return {...base,...t,simulations};
}

export function getLocalizedSubjectName(locale: Locale, slug: SubjectSlug) { return subjectFallbackNames[locale][slug]; }

export function displayDifficulty(locale: Locale, difficulty: SimulationCard["difficulty"]) {
  const g=getEducationCopy(locale).generic;
  return difficulty === "Beginner" ? g.beginner : difficulty === "Intermediate" ? g.intermediate : g.advanced;
}

export function displayOpportunity(locale: Locale, opportunity?: SimulationCard["opportunity"]) {
  if (!opportunity) return "";
  const g=getEducationCopy(locale).generic;
  if (opportunity === "Very High") return g.priorityVeryHigh;
  if (opportunity === "High") return g.priorityHigh;
  if (opportunity === "Medium–High") return g.priorityMediumHigh;
  return g.priorityMedium;
}
